rules.rego:
violation contains msg if {
	input.asset.tags.dataClass == "payment"
	input.asset.tags.originJurisdiction == "IN"
	not input.asset.location in data.in.payment_storage_allowed
	msg := sprintf("IN-RBI-PAYDATA-001: Indian payment data stored in %s; must be stored in India", [input.asset.location])
}
